import React from "react";
import {FontAwesomeIcon} from "@fortawesome/react-fontawesome";
import {
  faMapMarkerAlt,
  faPhone,
  faEnvelope,
} from "@fortawesome/free-solid-svg-icons";

function Footer() {
  return (
    <footer className="relative min-h-[33vh] flex flex-col">
      {/* Two-column Layout for Form and Location */}
      <div
        className="grid grid-cols-1 md:grid-cols-2 gap-5 p-5"
        style={{
          height: "33%",
          background:
            "linear-gradient(to bottom, #18181b 80% 80%, #c2410c  20%)",
        }}
      >
        {/* Contact Form Section */}
        <div className="text-white bg-black p-4 shadow-lg">
          <h1
            className="text-3xl font-semibold text-center"
            style={{fontFamily: "Aldhabi, serif"}}
          >
            Get in Touch
          </h1>
          <form
            action="https://fabform.io/f/{form-id}"
            method="post"
            className="space-y-3 mt-4"
          >
            <input
              className="w-full p-2 rounded border-b border-dashed bg-black text-white placeholder-white focus:outline-none focus:ring-2 focus:ring-orange-500"
              type="text"
              placeholder="Name"
              name="name"
            />
            <input
              className="w-full p-2 rounded bg-black border-b border-dashed text-white placeholder-white focus:outline-none focus:ring-2 focus:ring-orange-500"
              type="email"
              placeholder="Email"
              name="email"
            />
            <input
              className="w-full p-2 rounded bg-black border-b border-dashed text-white placeholder-white focus:outline-none focus:ring-2 focus:ring-orange-500"
              type="text"
              placeholder="Message"
              name="_subject"
            />
            <div className="flex justify-center mt-3">
              <button className="border-orange-500 border text-white hover:bg-orange-700 py-2 px-4 rounded-md shadow-md transition duration-300">
                SEND MESSAGE
              </button>
            </div>
          </form>
        </div>

        {/* Location Section */}
        <div className="text-white mt-5 md:mt-0 text-center">
          <h2
            className="text-6xl  align-middle"
            style={{fontFamily: "Aldhabi, serif"}}
          >
            Our Location
          </h2>
          <div className="space-y-4 text-center flex flex-col items-center justify-center">
            <div className="space-y-8 items-center mt-4">
              <div className="flex items-center">
                <FontAwesomeIcon
                  icon={faMapMarkerAlt}
                  className="mr-2"
                  style={{fontSize: "1.5rem"}}
                />
                <span
                  className="text-2xl"
                  style={{fontFamily: "Aldhabi, serif", fontWeight: "100"}}
                >
                  Khaldeh, Lebanon
                </span>
              </div>
              <div className="flex items-center">
                <FontAwesomeIcon icon={faPhone} className="mr-2" />
                <span
                  className="text-3xl"
                  style={{fontFamily: "Aldhabi, serif", fontWeight: "300"}}
                >
                  +961 03 730 627
                </span>
              </div>
              <div className="flex items-center">
                <FontAwesomeIcon
                  icon={faEnvelope}
                  className="mr-2"
                  style={{fontSize: "1.5rem"}}
                />
                <span
                  className="text-2xl"
                  style={{fontFamily: "Aldhabi, serif", fontWeight: "100"}}
                >
                  info@spicyfoodlb.com
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Footer Bottom Section */}
    </footer>
  );
}

export default Footer;
